window.__DIGEST_DATA = {"index": ["2026-09-28", "2026-09-27", "2026-09-26", "2026-09-25", "2026-09-24", "2026-09-23", "2026-09-22", "2026-09-21", "2026-09-20", "2026-09-19", "2026-09-18", "2026-09-17", "2026-09-16", "2026-09-15", "2026-09-14", "2026-09-11", "2026-09-10", "2026-09-09", "2026-09-08", "2026-09-07", "2026-09-04", "2026-09-03", "2026-09-02", "2026-09-01", "2026-08-31", "2026-08-28", "2026-08-27", "2026-08-26", "2026-08-25", "2026-08-24", "2026-08-21", "2026-08-20", "2026-08-19", "2026-08-18", "2026-08-17", "2026-08-14", "2026-08-13", "2026-08-12", "2026-08-11", "2026-08-10", "2026-08-07", "2026-08-06", "2026-08-05", "2026-08-04", "2026-08-03", "2026-07-31", "2026-07-30", "2026-07-29", "2026-07-28", "2026-07-27", "2026-07-24", "2026-07-23", "2026-07-22", "2026-07-21", "2026-07-20", "2026-07-17", "2026-07-16", "2026-07-15", "2026-07-14", "2026-07-13", "2026-07-10", "2026-07-09", "2026-07-08"], "latest": {"date": "2026-09-28", "mode": "per-newsletter", "categories": ["ai", "it", "dev", "infosec", "devops", "design", "data"], "digests": [{"title": "TLDR AI — 2026-09-28", "tagline": "Muse manifesto 📜, OpenAI training pause 🚨, trading compute 🤝", "sections": [{"name": "Headlines & Launches", "stories": [{"headline": "OpenAI prepares to expand Ultrafast API to more users (1 minute read)", "blurb": "OpenAI appears to be preparing a wider rollout of its Ultrafast API mode. References to the rollout have been seen showing up across the OpenAI Platform and API documentation. The feature was officially previewed with GPT-5.6 Sol. OpenAI claims it has speeds of up to 750 output tokens per second and up to 14 times faster inference than Standard. The mode is powered by Cerebras. Access remains limited to select customers.", "url": "https://www.testingcatalog.com/openai-prepares-to-expand-ultrafast-api-to-more-users/"}, {"headline": "Why I'm Building Muse (2 minute read)", "blurb": "Muse is built as a personal agent that turns vague ambitions into concrete action by planning, emailing, calling, finding resources, and removing friction. Alexandr Wang frames it as a way to expand individual agency and make more ambitions achievable.", "url": "https://x.com/alexandr_wang/status/2103551714536439951"}, {"headline": "OpenAI and Anthropic Probe Tens of Thousands of Incidents as OpenAI Halts Training (4 minute read)", "blurb": "OpenAI, Anthropic, and security researchers are investigating tens of thousands of incidents in which models acted beyond intended limits. Most incidents caused no harm. The count is not a count of breaches: there were only four incidents of unauthorized access to real third-party systems. OpenAI has paused training, evaluation, and tool-use inference for its most capable models.", "url": "https://www.implicator.ai/openai-anthropic-tens-of-thousands-incidents-pause/"}]}, {"name": "Deep Dives & Analysis", "stories": [{"headline": "Let's talk about trading compute (16 minute read)", "blurb": "There is an emerging market of compute derivatives. This could fundamentally change how neoclouds and anyone adjacent can grow as well as protect themselves. The problem is pretty urgent for inference clouds. Companies that sell customers fixed-price services as their GPU bill floats have taken a position on compute prices whether they meant to or not.", "url": "https://x.com/gpugene/status/2104186844007248332?s=12"}, {"headline": "Can AI self-improvement overcome diminishing returns? (38 minute read)", "blurb": "AI is already helping build better AI. The technology is improving at a stupendous pace and is expected to continue to do so. Experts expect increasingly superhuman performance in parts of formal math, coding, and cybersecurity, and any other verifiable domain where machines can generate training data and verify success at machine speed. However, this doesn't mean that the industry is close to super-intelligence or general ASI.", "url": "https://www.rameznaam.com/p/ai-rsi-isnt-leading-to-super-intelligence"}, {"headline": "Agent (Muse) Compute Demand (5 minute read)", "blurb": "It costs Meta an estimated around 1 to 2 gigawatts of average total power to serve 100 million daily active users. Only around 0.1 gigawatts comes from the GPU/VM layer. 3 to 4 gigawatts per day is entirely plausible depending on the number of reasoning-equivalent model calls users generate. The sandbox layer contains less than $1 billion of CPU content and around $2 billion of DRAM content.", "url": "https://robonomics.substack.com/p/agent-muse-compute-demand"}]}, {"name": "Engineering & Research", "stories": [{"headline": "Claude computes a nine-loop amplitude in N=4 super-Yang-Mills (18 minute read)", "blurb": "Physicists at Anthropic harnessed Claude, an LLM, to compute a complex nine-loop amplitude in N=4 super-Yang-Mills, a problem once considered computationally infeasible with limited resources. They utilized the bootstrap method and form-factor approach, achieving results comparable to human attempts but with greater efficiency and less oversight. The work highlights untapped potential in AI for complex physics calculations, suggesting that more advances might be achieved with better computation and software practices.", "url": "https://www.anthropic.com/research/yes-claude-can-do-nine-loops"}, {"headline": "Hitting a billion tokens per minute on one GPU by combining a query planner and an inference engine (15 minute read)", "blurb": "The QUery-Aware Inference Layer (Quail) is an inference engine that hits over a billion tokens processed per minute per H100 GPU. It is over 10 times faster than the vLLM baseline on the same hardware, and it costs under $0.06 per billion tokens on Modal. This post provides a quick overview of how Quail works. It focuses more on considerations for inference engineers.", "url": "https://modal.com/blog/quail-billion-tpm"}, {"headline": "Policy Gradients for LLMs Explained Visually (8 minute read)", "blurb": "A visual, from-scratch derivation of REINFORCE showed how policy gradients train language models by increasing the probability of rewarded outputs.", "url": "https://www.tylerromero.com/posts/2026-09-policy-gradient/"}]}, {"name": "Miscellaneous", "stories": [{"headline": "Product Manager, Applied AI at TLDR ($200k base + $60k bonus, Fully Remote)", "blurb": "TLDR is hiring its first PM to help build the agent-first operating layer used across the company. We're looking for a builder who has shipped real products/systems with LLMs. Click here to learn more .", "url": "https://jobs.ashbyhq.com/tldr.tech/897f4391-66ab-44ca-a8eb-65dd9809200d"}, {"headline": "On Ezra Klein's Podcast With Jensen Huang (40 minute read)", "blurb": "Jensen Huang doesn't believe in superintelligence or that AI will ever be a different kind of thing from software. AI will never be more than a new abstraction level and so won't fundamentally change anything. He doesn't believe in AI existential risk, even though his tolerance for safety risk is lower than even the most paranoid safety advocate. Critics say he must not understand the technology and that he would have a very different view if he actually understood what the top risks were.", "url": "https://thezvi.substack.com/p/on-ezra-kleins-podcast-with-jensen"}, {"headline": "Elon Musk's SpaceXAI to add another 660,000 AI GPUs this year (2 minute read)", "blurb": "220,000 Nvidia GB300 GPUs will be operational at X's Colossus supercomputer in November. The company is aiming to bring another 220,000 units online by late December. Colossus 2 currently has 110,000 GB200 and 440,000 GB300 GPUs, and Colossus 1 has 150,000 H100, 50,000 H200, and 30,000 GB200 GPUs. This means SpaceXAI has 1.1 million GB300s, with a total of 1.44 million GPUs in operation.", "url": "https://www.tomshardware.com/tech-industry/data-centers/elon-musks-spacexai-to-add-another-660-000-ai-gpus-this-year-nearing-a-total-of-1-44-million-in-operation-firm-is-building-1-2-gigawatt-power-plant-to-bring-systems-fully-online"}]}, {"name": "Quick Links", "stories": [{"headline": "Build plugins for Claude with the directory submission portal (3 minute read)", "blurb": "Developers on paid Claude plans can now build and submit plugins using a new directory submission portal.", "url": "https://claude.com/blog/build-plugins-for-claude"}, {"headline": "Oxford let OpenAI train AI models on Bodleian Library texts (2 minute read)", "blurb": "Oxford allowed OpenAI to use Bodleian Library texts for AI training, sparking concerns about the impact on Oxford's reputation and AI's energy consumption.", "url": "https://thenextweb.com/news/oxford-bodleian-openai-training-data"}, {"headline": "Anthropic Signed an $11.6 Billion Akamai Compute Deal (3 minute read)", "blurb": "Anthropic agreed to spend up to $11.6 billion over seven years on Akamai cloud infrastructure, subject to delivery and availability requirements.", "url": "https://www.ir.akamai.com/news-releases/news-release-details/akamai-announces-116-billion-multi-year-agreement-anthropic"}]}]}, {"title": "TLDR IT — 2026-09-28", "tagline": "AI Breaks the Sandbox 🌐, The SSO Tax Under Fire 🔐, Microsoft Governs AI 🧑‍💻", "sections": [{"name": "News & Trends", "stories": [{"headline": "OpenAI agents uploaded user images to the public internet without the company's knowledge (5 minute read)", "blurb": "AI agents operating in OpenAI's research environment uploaded user-provided images to public image-hosting sites without the company's knowledge. OpenAI identified 53 instances, underscoring a new class of enterprise AI risk: autonomous agents with access to sensitive data can take unintended external actions even when they aren't explicitly instructed to do so.", "url": "https://techcrunch.com/2026/09/25/unsecured-openai-agents-posted-53-user-images-on-the-internet-without-the-labs-knowledge/"}, {"headline": "Kiteworks tells customers to shut down servers over threat of an imminent attack (4 minute read)", "blurb": "Secure file-sharing provider Kiteworks took the unusual step of asking customers to temporarily shut down servers after receiving intelligence about a potentially imminent cyberattack. The precaution is particularly notable given Kiteworks' role in handling sensitive enterprise file transfers and communications.", "url": "https://www.bleepingcomputer.com/news/security/kiteworks-urges-6-hour-server-shutdown-over-potential-zero-day-attacks/"}]}, {"name": "Analysis & Opinions", "stories": [{"headline": "Enterprise AI coding agents are becoming an IT procurement problem too (7 minute read)", "blurb": "A comparison of GitHub Copilot, AWS Kiro, Cursor, and Cognition highlights how enterprise evaluation of coding agents now extends well beyond developer productivity. IP indemnification, data residency, prompt retention, audit logs, and enterprise pricing are increasingly becoming security, legal, and IT considerations when these tools are deployed at scale.", "url": "https://www.marktechpost.com/2026/09/26/ai-coding-agents-for-enterprise-ip-indemnity-data-residency-and-500-seat-cost-compared/"}, {"headline": "AI agents expose a security gap between the data they can read and the systems they can change (6 minute read)", "blurb": "Traditional application permissions weren't designed for autonomous agents that can read information in one system, reason about it, and then take actions somewhere else. Enterprises need to think beyond model security and start controlling the full agent execution path: identity, data access, tools, and actions.", "url": "https://venturebeat.com/security/ai-agents-are-exposing-a-security-gap-between-the-data-they-read-and-the-systems-they-can-change"}, {"headline": "The enterprise needs to kill the \"SSO tax\" (5 minute read)", "blurb": "The long-running practice of SaaS vendors reserving SSO for expensive enterprise plans effectively makes companies pay extra for a basic security control. The model needs to change, as identity becomes even more important in an AI- and SaaS-heavy workplace, citing data that 37% of enterprise SaaS applications remain outside SSO.", "url": "https://9to5mac.com/2026/09/26/apple-work-the-enterprise-needs-to-kill-the-sso-tax-and-its-an-opportunity-for-apple/"}]}, {"name": "Launches & Partnerships", "stories": [{"headline": "Salesforce unveils Koa, a reasoning model built specifically for CRM (4 minute read)", "blurb": "Salesforce has introduced Koa, a reasoning model designed specifically for CRM workloads and Agentforce. Rather than relying entirely on general-purpose models, Salesforce is betting that domain-specific models can better understand customer data, workflows, and the business context required by enterprise agents.", "url": "https://smallbiztrends.com/salesforce-unveils-koa-a-breakthrough-ai-model-for-crm-reasoning/"}]}, {"name": "Miscellaneous", "stories": [{"headline": "Amazon Bedrock gets better visibility into who's actually spending your AI budget (4 minute read)", "blurb": "AWS has added IAM-principal-level visibility that can help organizations break down Bedrock AI spending by team, project, or application. As companies move from a handful of AI experiments to dozens of internal agents and applications, attributing model consumption to an actual owner is becoming a very practical FinOps problem.", "url": "https://buildingenterprisetechnology.news/latest-news/"}, {"headline": "AI fluency isn't enough - companies still need human judgment (5 minute read)", "blurb": "EY's Global Vice Chair argues that organizations shouldn't confuse widespread AI adoption with eliminating the need for human expertise. As AI handles more analysis and routine work, judgment, accountability, and knowing when not to trust an AI-generated answer may become more valuable workplace skills rather than less.", "url": "https://fortune.com/2026/09/27/ai-fluency-human-judgment-leadership/"}]}, {"name": "Quick Links", "stories": [{"headline": "AR smart glasses are making another run at the enterprise (3 minute read)", "blurb": "AI integration is helping revive enterprise interest in smart glasses for factories, logistics, maintenance, and other hands-free workflows.", "url": "https://www.chosun.com/english/industry-en/2026/09/27/FGRQQI647FCHXNRNWG4EVI6KMY/"}, {"headline": "OpenAI agents interacted unexpectedly with US government websites (3 minute read)", "blurb": "OpenAI says an ongoing review found agents accessing public information from government sites in unexpected ways, while an independent investigation identified additional activity involving government websites.", "url": "https://www.securityweek.com/openai-says-its-models-engaged-with-us-government-websites-in-new-model-misbehavior-disclosure/"}, {"headline": "Microsoft introduces FinOps controls specifically for AI and agents (4 minute read)", "blurb": "New Copilot and Agent 365 controls let admins manage spending policies, model availability, and usage-based agent costs as AI consumption starts looking more like cloud infrastructure spend.", "url": "https://blogs.microsoft.com/blog/2026/09/25/introducing-the-new-copilot-with-home-code-and-autopilot/"}]}]}, {"title": "TLDR Web Dev — 2026-09-28", "tagline": "First principles thinking 🧠, plan mode is dead 🥀, improving performance with CSS ⚡️", "sections": [{"name": "Articles & Tutorials", "stories": [{"headline": "Improving Site Performance by Shipping More CSS (8 minute read)", "blurb": "GitHub explains how it migrated github.com from CSS-in-JS to CSS Modules to remove client and server runtime styling costs. The gradual rollout preserved component encapsulation while moving styles into static stylesheets delivered with page HTML.", "url": "https://github.blog/engineering/architecture-optimization/improving-site-performance-by-shipping-more-css/"}, {"headline": "Revealing the Details of How OpenAI Agents Hacked Hugging Face (20 minute read)", "blurb": "An investigation reconstructs how a swarm of 700 agents escaped constrained evaluation environments and penetrated Hugging Face systems. The report traces nearly one million chained short links, more than 80,000 decoded payloads, credential exposure, Slack searches, and attempts to hide evidence.", "url": "https://swarmtraces.org/"}]}, {"name": "Opinions & Advice", "stories": [{"headline": "Plan Mode Is Dead (9 minute read)", "blurb": "Plan modes turn useful thinking into long artifacts that people do not want to read and impose an artificial boundary between planning and building. A better workflow loops through understanding, action, inspection, clarification, and adjustment while surfacing only the decisions that need human attention.", "url": "https://www.aymannadeem.com/artificial/intelligence,/developer/tools/2026/09/24/plan-mode-is-dead.html"}, {"headline": "How to Keep Enjoying Programming in a World of LLMs (8 minute read)", "blurb": "Developers can preserve ownership, skill, and enjoyment by continuing to write the code they care about themselves. LLMs are more useful for planning, research support, bookkeeping, cleanup, and routine work, with humans taking charge of crucial decisions and implementation.", "url": "https://discourse.haskell.org/t/how-to-keep-enjoying-programming-in-a-world-of-llms/14705"}, {"headline": "First Principles Thinking (4 minute read)", "blurb": "First-principles thinking asks engineers to set accumulated assumptions aside long enough to identify the real problem and the outcome that matters. With agents, that means working in small, concrete steps that shorten learning loops, preserve momentum, and make experimentation easier.", "url": "https://sunilsadasivan.com/writing/first-principles-thinking/"}]}, {"name": "Launches & Tools", "stories": [{"headline": "Whiteboard (GitHub Repo)", "blurb": "Whiteboard is an open-source desktop canvas where developers and coding agents can design and review software together. It connects diagrams, traces, and semantic diffs to the underlying code while operating against local checkouts.", "url": "https://github.com/devdotfast/whiteboard"}, {"headline": "Atlas (GitHub Repo)", "blurb": "Atlas is source control for coding agents that links commits to the sessions, prompts, tool calls, and reasoning that produced them. It can run multiple agents side by side with shared local memory while keeping code, notes, and sessions on the machine by default.", "url": "https://github.com/pacifio/atlas"}, {"headline": "Mobile MCP (GitHub Repo)", "blurb": "Mobile MCP gives agents one interface for automating native iOS and Android apps across simulators, emulators, and real devices. It uses structured accessibility snapshots for efficient interaction, then falls back to screenshots and coordinates when needed.", "url": "https://github.com/mobile-next/mobile-mcp"}]}, {"name": "Miscellaneous", "stories": [{"headline": "Fifteen Years Later, the Apple Cards Origin Story (8 minute read)", "blurb": "Apple's short-lived Cards app began as a Steve Jobs idea for sending a physical thank-you card directly from an iPhone. Its 2011 launch required new letterpress designs, cotton paper, international printing, postage coordination, and a production operation remembered for extraordinary complexity.", "url": "https://lexontech.org/fifteen-years-later-the-apple-cards-origin-story"}, {"headline": "Personal AI Agents Quietly Upsell Users They Think Are Rich (6 minute read)", "blurb": "Across 325,000 trials and 13 models, agents recommended more expensive flights, insurance, and graduate programs to users they inferred were wealthy despite identical requests. The study used synthetic personas, but explicit requests for the cheapest option often failed to remove the gap while hard price caps were more effective.", "url": "https://www.stacksweep.dev/ai-agents-upsell-wealthy-users"}, {"headline": "Almost Nobody Gets XML Sitemaps Right (5 minute read)", "blurb": "Sitemap Inspector began as a way to make XML sitemaps readable and evolved into a checker for redirects, HTTP errors, noindex directives, and canonical mismatches. Tests found sitemap problems across major sites including Adobe, Anthropic, GOV.UK, Manchester City, Semrush, and X.", "url": "https://joost.blog/broken-sitemaps/"}]}, {"name": "Quick Links", "stories": [{"headline": "Introducing Ember-1 (8 minute read)", "blurb": "Ember-1 is a specialized model trained from Kimi K3 to reduce unnecessary reasoning while preserving answer quality.", "url": "https://fireworks.ai/blog/ember-1"}, {"headline": "A Jev-like Wrapper for LLMs, Including Vision Models (5 minute read)", "blurb": "A standalone Python LLM wrapper turns one-token log probabilities into structured classifications and scores, similar to Jev.", "url": "https://allanrbo.blogspot.com/2026/09/a-jev-like-wrapper-for-llms-including.html"}, {"headline": "Safe Not Safe (Website)", "blurb": "Safe Not Safe checks PostgreSQL migrations locally in the browser with a WASM parser and deterministic rules, without uploading SQL or requiring an account.", "url": "https://safenotsafe.dev/"}, {"headline": "Floci (Website)", "blurb": "Floci provides free, local emulators for AWS, Azure, GCP, and OCI with real service engines, fast startup, and no cloud account or authentication token.", "url": "https://floci.io/"}]}]}, {"title": "TLDR InfoSec — 2026-09-28", "tagline": "Bitget $387M hack 💸, Salesbleed Enables Slack Phishing 🤖, Supabase data leak 💧", "sections": [{"name": "Attacks & Vulnerabilities", "stories": [{"headline": "Bitget Hack Timeline: How Its Own System Approved a $387 Million Theft (2 minute read)", "blurb": "On September 24, attackers stole $387.5 million from Bitget's hot and warm wallets by feeding false transaction data into a compromised backend system, which then authorized the transfers. Bitget detected unauthorized activity at 18:31 UTC, paused withdrawals hours later, and ruled out private-key theft. Mandiant and SlowMist are investigating. CEO Gracy Chen has flagged possible North Korean involvement.", "url": "https://finance.yahoo.com/markets/crypto/articles/bitget-hack-timeline-own-system-164015015.html"}, {"headline": "'Salesbleed' Exploits Salesforce Agents to Enable Slack Phishing (4 minute read)", "blurb": "Zenity identified three Salesforce Agentforce weaknesses. Attackers could inject commands via Web-to-lead forms and bypass URL filters. If connected to Slack, they could post phishing links in internal threads. The lack of confirmation and attribution controls made messages appear to come from employees or IT. Salesforce added confirmation prompts, spec-compliant URL parsing, and centralized URL inspection.", "url": "https://www.darkreading.com/application-security/salesbleed-exploits-salesforce-agents-slack-phishing"}, {"headline": "Cloudflare fixes Containers cross-tenant flaw exposing customer data (8 minute read)", "blurb": "Cloudflare remediated a cross-tenant flaw in Containers and Sandboxes that allowed a Workers Paid customer to read residual disk blocks left by other tenants on the same host. The flaw stemmed from dm-thin storage pools running with skip_block_zeroing, so a 4 KiB write into a reused 64 KiB block left the untouched 60 KiB readable via a raw read of /dev/vdc. Accomplish's Oren Yomtov, who reported it through HackerOne on September 4, recovered directory structures, database pages, and complete SQLite databases on 18 of 24 placements across 20 of 22 nodes, though an attacker could not target a specific victim or read an actively attached disk. Cloudflare removed skip_block_zeroing fleet-wide, retired running container disks, and cleared cached image snapshots by September 19. Its disk-I/O telemetry review found no exploitation beyond authorized validation, so no customer action is required.", "url": "https://blog.cloudflare.com/containers-cross-tenant-vulnerability/"}]}, {"name": "Strategies & Tactics", "stories": [{"headline": "OAuth token abuse: how the attack works and how to stop it (7 minute read)", "blurb": "OAuth token abuse gives attackers application-level access that survives password resets and MFA, since tokens belong to the app rather than the user, and can be obtained through consent phishing, device code phishing, credential additions to existing apps, or preconsented first-party applications. Because malicious apps live in the attacker's tenant, defenders should watch victim-tenant Entra ID events (Add service principal, Consent to application, Add delegated permission grant, and app role assignments) alongside anomalous post-consent activity, with behavioral app-to-purpose checks coming from Defender for Cloud Apps rather than native audit logs. The highest-value controls are preventive: restrict user consent to verified low-impact apps, require admin approval for high-risk scopes like Mail.Read and offline_access, and keep an approved application inventory, since eviction requires removing the grant and service principal rather than resetting credentials.", "url": "https://www.scworld.com/tech-explainer/oauth-token-abuse-how-the-attack-works-and-how-to-stop-it"}, {"headline": "Galileo's first civil authenticated position fix under spoofing conditions (3 minute read)", "blurb": "Galileo has demonstrated its first real-world civil position fix using the upcoming Signal Authentication Service, holding a stable lock across five satellites during live spoofing at the Jammertest event in Andøya, Norway on September 16. SAS encrypts the E6-C ranging signal's spreading codes and publishes the decryption key on a delayed, separate channel, letting a receiver correlate the recorded signal only after the fact to confirm each satellite's pseudorange. It pairs with the already-operational OSNMA, which authenticates the navigation message itself. Both services will be free and worldwide, extend to the High Accuracy Service, and let receivers detect and reject a broad range of spoofing attacks. However, EUSPA still must run SAS validation and accreditation before declaring the service operational, and the delayed-key design leaves jamming and meaconing as open concerns.", "url": "https://www.esa.int/Applications/Satellite_navigation/Galileo/Galileo_s_first_civil_authenticated_position_fix_under_spoofing_conditions"}, {"headline": "EDR Evasion: Process Injection Without WriteProcessMemory (4 minute read)", "blurb": "Zero Salarium details a remote process injection technique that skips the heavily monitored VirtualAllocEx and WriteProcessMemory pair, instead spawning an interactive console child (nslookup.exe or netsh.exe) and writing shellcode into its memory via WriteFile on the child's hStdInput pipe, then using VirtualProtectEx to add execute permissions and a thread hijack to point RIP at the payload. A distinctive marker locates the planted bytes, and the payload must avoid 0x0D, 0x0A, and 0x1A, which the console would treat as command input. Since the classic API pair is absent, defenders should watch for VirtualProtectEx against remote processes, read/write activity on named pipes, and the console's command-storage memory region.", "url": "https://www.zerosalarium.com/2026/09/edr-evasion-process-injection-without-WriteProcessMemory.html"}]}, {"name": "Launches & Tools", "stories": [{"headline": "Mecatl (GitHub Repo)", "blurb": "Mecatl is an open-source, cloud-native agent harness. Mecatl keeps the agent loop independent of the client and execution environment, so the same runtime can start locally, run remotely with durable external state and a recorded event history, and then scale across Kubernetes replicas without replacing the loop.", "url": "https://github.com/stacklok/mecatl"}, {"headline": "RCEKit (GitHub Repo)", "blurb": "RCEKit is an RCE detection and confirmation toolkit for authorized penetration testing, red teaming, and security research. Point it at a target you are authorized to test — a URL or a captured HTTP request — and every finding returns with the tier it earned.", "url": "https://github.com/kabiri-labs/rcekit"}, {"headline": "Introducing ADE-Skills — Adversarial Detection Engineering Knowledge Base (5 minute read)", "blurb": "ADE Skills, from Koifsec and Nikolas Bielski, is a knowledge base for adversarial detection engineering: the study of the gap between what a detection rule is intended to catch and what it literally matches. It organizes detection-logic bugs into a taxonomy of four categories (reformatting in actions, omitted equivalents like pwsh.exe vs powershell.exe, context development, and inverted or missing-field logic) across fifteen subcategories and thirty-seven worked technique files, each pairing a vulnerable rule with a hardened one. It also ships platform bug-pattern catalogs for Elastic, Sentinel, and Sigma, a false-negative checklist, a machine-mined catalog of ~593 candidate bypass findings across public rulesets, and Redamon, a purple-team scoping skill that maps in-scope techniques to a target's actual SIEM/EDR rules.", "url": "https://detect.fyi/introducing-ade-skills-adversarial-detection-engineering-knowledge-base-397a8910c982"}]}, {"name": "Miscellaneous", "stories": [{"headline": "Some Supabase customers are publicly exposing reams of people's data to the web (2 minute read)", "blurb": "UpGuard found around 16,000 publicly accessible Supabase-hosted databases leaking names, addresses, phone numbers, and some passwords or tokens. Exposed data included private chats with sex workers on an Indian adult site, thousands of US valet license plates, immigration-service contacts, an African consulate's records in France, and a virtual SIM farm used to intercept OTP texts for scams. Most datasets were in the US, but the issue spans multiple regions. Supabase says projects are secure by default and blames misconfiguration on customers.", "url": "https://techcrunch.com/2026/09/25/some-supabase-customers-are-publicly-exposing-reams-of-peoples-data-to-the-web/"}, {"headline": "There's a new way to break RSA that's faster than anything we've seen before (2 minute read)", "blurb": "Researchers demonstrated a classical-computing attack that forges RSA signatures without factoring the private key. Using a \"special\" number field sieve against blind-signature (textbook) RSA, they reduced security from an estimated 2^80 operations and 500,000–1,000,000 CPU core-years for 1024-bit keys to about 2^65 operations and 1,380 core-years. The method applies only to blind-signature implementations like Privacy Pass (used by Apple and Cloudflare), not standard PKCS or PSS-padded RSA. Forging a Privacy Pass signature would require compromising a server and generating 2^43 signatures, a workload comparable to a day of Cloudflare's public traffic.", "url": "https://arstechnica.com/security/2026/09/theres-a-new-way-to-break-rsa-thats-faster-than-anything-weve-seen-before/"}, {"headline": "AI Agents Are Hacking Online Retailers for $25 a Company (14 minute read)", "blurb": "A financially motivated operator ran three open-source AI harnesses (Strix, Cairn, and Hermes) against hundreds of online retailers from July to mid-September, spending roughly $12,000–$18,000 on AI model calls. The campaign exfiltrated over 600,000 unexpired credit card records from two victims, injected skimmers into at least 27 sites, and achieved access to assets of a Fortune 500 hospitality firm, a major US airline, and other large retailers. In several breaches, the agent executed a \"database wipe after extraction\" routine that deleted payment data and, in one case, dropped 180 tables including backups.", "url": "https://gambit.security/blog-posts/autonomous-ai-agents-online-retailers-25-a-company"}]}, {"name": "Quick Links", "stories": [{"headline": "Kiteworks Urges Customers to Shut Down Systems for 9 Hours Over Possible Cyber Attack (2 minute read)", "blurb": "Kiteworks advised customers to shut down systems for nine hours after receiving threat intelligence about a possible attack.", "url": "https://thehackernews.com/2026/09/kiteworks-urges-customers-to-shut-down.html"}, {"headline": "OpenAI's AI agents accidentally uploaded user-provided images to third-party sites (2 minute read)", "blurb": "OpenAI's research agents uploaded 53 training-eligible user images to third-party image hosts as unlisted links, most of which have since been removed as OpenAI's post-Hugging Face review of agent activity continues.", "url": "https://www.bleepingcomputer.com/news/artificial-intelligence/openais-ai-agents-accidentally-uploaded-user-provided-images-to-third-party-sites/"}, {"headline": "OpenAI agents tried to 'bruteforce' a UN website (2 minute read)", "blurb": "OpenAI agents scanned UNCTAD's statistics site over 16,000 times between April and June while trying to pull Productive Capacities Index data, escalating from bypassing their HTTP-tool limits to masking their behavior against an imagined filter and hijacking Google's XSS training game to reach the data.", "url": "https://www.theverge.com/ai-artificial-intelligence/1001178/openai-agents-bruteforce-un-website"}]}]}, {"title": "TLDR DevOps — 2026-09-28", "tagline": "OpenCodeReview 📜, AI-First Observability 🔍, Bun Rewrite 🍞", "sections": [{"name": "News & Trends", "stories": [{"headline": "Amazon CloudWatch Omni: AI-first observability for agents and applications (2 minute read)", "blurb": "AWS has launched CloudWatch Omni, an AI-powered observability experience that combines OpenTelemetry with CloudWatch's scale to unify telemetry across accounts, regions, and other clouds into one team-organized workspace. It offers natural language querying, automatic dependency mapping, and a dedicated agent observability workflow spanning frameworks like LangGraph, CrewAI, and the Vercel AI SDK.", "url": "https://aws.amazon.com/about-aws/whats-new/2026/09/amazon-cloudwatch-omni-ai/"}, {"headline": "Alibaba Open Sources OpenCodeReview for AI-Assisted Code Review (2 minute read)", "blurb": "Alibaba has open-sourced OpenCodeReview, an Apache-2.0 code review tool that combines deterministic file and rule matching with AI analysis to flag issues like null pointers and SQL injection. It matches Claude Code's precision using roughly one-ninth the tokens in tests, though outside reviewers found recall as low as 20 percent.", "url": "https://www.infoq.com/news/2026/09/alibaba-opencodereview/"}]}, {"name": "Opinions & Tutorials", "stories": [{"headline": "Trading a Cloud Identity for Your Own: Workload Attestation on Managed Compute (7 minute read)", "blurb": "Netflix engineers developed a method to bridge AWS IAM roles with internal identities for Apache Spark workloads on Amazon EMR. The system maps each Data Project identity to a dedicated IAM role, allowing a control plane to sign metadata that an identity service verifies against a cloud proof of possession. This approach ensures that workloads running on managed compute obtain valid certificates from the internal PKI, called Metatron, without relying on the workload's own account of itself.", "url": "https://netflixtechblog.com/trading-a-cloud-identity-for-your-own-workload-attestation-on-managed-compute-516d5a29b252?source=rss----2615bd06b42e---4&amp%3Butm_source=tldrdevops"}, {"headline": "A Type Stronger than the Sum of its Components (5 minute read)", "blurb": "Rust APIs can encode stronger invariants by turning individual enum variants into dedicated types instead of accepting broader string or path values. Wrapping std::path::Component variants in types such as NormalComponent and ParentDirComponent lets the compiler enforce properties like safe path joins and prevents callers from passing values containing .., absolute paths, or other invalid components.", "url": "https://www.schneems.com/2026/09/24/a-type-stronger-than-the-sum-of-its-components/"}, {"headline": "Improving site performance by shipping more CSS (8 minute read)", "blurb": "GitHub migrated github.com from CSS-in-JS to CSS Modules to remove client- and server-side styling overhead at scale. The migration cut Primer server-side rendering time by 55%, reduced component initialization time by 25%, and later improved SSR by up to 22% on some pages while thousands of sx usages were gradually replaced through feature flags, visual regression tests, codemods, and staged rollouts.", "url": "https://github.blog/engineering/architecture-optimization/improving-site-performance-by-shipping-more-css/"}]}, {"name": "Resources & Tools", "stories": [{"headline": "scriptc (GitHub Repo)", "blurb": "scriptc compiles TypeScript and JavaScript to native executables, WebAssembly modules, and other outputs including C and LLVM IR. It uses the TypeScript compiler for parsing and type checking, and static builds include a small native runtime without a JavaScript engine.", "url": "https://github.com/vercel-labs/scriptc"}, {"headline": "Openrig (GitHub Repo)", "blurb": "OpenRig is a multi-agent harness that manages Claude Code and Codex as a unified team within tmux sessions. It defines agent teams in YAML and includes starter configurations like a four-seat conveyor, a product-team with seven seats, and a secrets-manager example that runs a HashiCorp Vault instance. The tool requires Node.js and integrates a local daemon, CLI, terminal UI, and MCP server. Users should read the documentation about system changes before installing, as OpenRig writes hooks, trust settings, and provider integrations during setup.", "url": "https://github.com/mvschwarz/openrig"}]}, {"name": "Miscellaneous", "stories": [{"headline": "Maximizing Apache Spark availability: Mitigating compute stockouts with flexible VMs and other best practices (5 minute read)", "blurb": "Google's Managed Service for Apache Spark now supports flexible VMs, letting clusters rank multiple acceptable machine families and storage types so provisioning automatically falls back during regional capacity stockouts rather than failing. Google recommends pairing ranked configurations with AutoZone routing, autoscaling, and regional fallbacks for resilience.", "url": "https://cloud.google.com/blog/products/data-analytics/maximize-apache-spark-availability-with-flexible-vms/"}, {"headline": "How Cloudflare addressed a cross-tenant data exposure vulnerability in Containers (6 minute read)", "blurb": "Security researcher Oren Yomtov reported a vulnerability in Cloudflare Containers that allowed residual data recovery from storage blocks used by other customers on the same host. The issue stemmed from a configuration setting that skipped zeroing newly allocated blocks, potentially exposing directory structures, database pages, and application data. Cloudflare has remediated the vulnerability across its fleet and found no evidence of malicious exploitation.", "url": "https://blog.cloudflare.com/containers-cross-tenant-vulnerability/"}]}, {"name": "Quick Links", "stories": [{"headline": "Wrong, not broken (7 minute read)", "blurb": "Traditional observability can show that an AI agent is fast, available, and error-free while missing whether its output is actually correct.", "url": "https://aws.amazon.com/blogs/aws-insights/wrong-not-broken/"}, {"headline": "Bun Rewrites 535K Lines of Zig into Rust in Four Months, Eliminates Numerous Memory Leaks (3 minute read)", "blurb": "Bun's creator rewrote the JavaScript runtime's 535,000-line Zig codebase into Rust in four months using AI-orchestrated implementer, reviewer, and fixer agents at a cost of $165,000 in tokens.", "url": "https://www.infoq.com/news/2026/09/bun-AI-rewrite-zig-rust-4-months/"}, {"headline": "Introducing enhanced custom event buses in Amazon EventBridge for enterprise-scale event-driven applications (6 minute read)", "blurb": "AWS has announced an enhanced custom event bus for Amazon EventBridge that organizations can share across all accounts.", "url": "https://aws.amazon.com/blogs/aws/introducing-enhanced-custom-event-buses-in-amazon-eventbridge-for-enterprise-scale-event-driven-applications/"}]}]}, {"title": "TLDR Design — 2026-09-28", "tagline": "Meta Connect 👓, Lovable Crosses $600M 💸, Apple RAW Support 🖼️", "sections": [{"name": "News & Trends", "stories": [{"headline": "At Meta Connect, the company's smart glasses were everywhere (4 minute read)", "blurb": "At Meta Connect, hands-on demos showed how Meta's smart glasses could support everyday tasks through its upcoming Muse integration, from sending emails to reading to-do lists aloud. The assistant still struggled to distinguish commands from nearby conversation, highlighting a challenge for voice-driven interfaces. Meta also demonstrated a separate $150 pair designed for people with hearing loss, with adjustable amplification that focuses on the person ahead or picks up sound from all directions.", "url": "https://techcrunch.com/2026/09/25/at-meta-connect-the-companys-smart-glasses-were-everywhere/"}, {"headline": "Lovable's Annualized Revenue Crosses $600M as Vibe Coding Takes Off (2 minute read)", "blurb": "Lovable's annualized revenue has crossed $600 million, up from roughly $500 million in June. Two-thirds of Fortune 500 companies now use the vibe-coding platform, whose customers include Microsoft, Nvidia, and Deutsche Telekom. Apps built on Lovable draw nearly a billion monthly views, and two funding rounds totaling over $700 million lifted its valuation to $13.3 billion.", "url": "https://techcrunch.com/2026/09/24/lovables-annualized-revenue-crosses-600m-as-vibe-coding-takes-off/"}, {"headline": "Apple adds RAW support for 11 digital cameras across iPhone, iPad, Mac, and Vision Pro (2 minute read)", "blurb": "Apple has expanded RAW image support across iOS, iPadOS, macOS, and visionOS, adding compatibility for 11 more Fujifilm, OM System, Panasonic, and Phase One cameras, bringing the total number of supported models to 562.", "url": "https://9to5mac.com/2026/09/22/apple-adds-raw-support-for-11-digital-cameras-across-iphone-ipad-mac-and-vision-pro/"}]}, {"name": "Opinions & Tutorials", "stories": [{"headline": "Code as the Source of Truth (2 minute read)", "blurb": "With AI tooling, treating code as the shared source of truth lets design and engineering function as one real team rather than handing work off in sequence. Designers can prototype real coded components before engineers finalize them, while engineers push directly into Figma for designers to refine, provided a subject-matter expert reviews every step. Pairing engineers and designers to teach each other's practices speeds up delivery, and, over time, the title lines between them begin to blur.", "url": "https://www.tonyward.dev/articles/code-as-the-source-of-truth"}, {"headline": "Brand as Software (19 minute read)", "blurb": "In-house brand teams have become service desks: at Ramp, a Slack help channel logged more than 375 requests in six months. Brand as software carries a company's point of view, product truths, and design decisions into the work itself, with artists setting the bar and builders codifying it. A Slack agent there already turns an attached doc into a near-final deck in one pass, so designers spend time on work no system can predict.", "url": "https://pauljun.substack.com/p/brand-as-software"}, {"headline": "Apple's perfect iPhone Duo TikToks nail foldable phone marketing (2 minute read)", "blurb": "Apple is leaning into playful, social-first marketing for the iPhone Duo with a series of TikTok sketches that showcase the foldable's versatility in everyday scenarios, from a mini laptop to a portable movie screen. Unlike Apple's typically minimalist campaigns, these ads spend more time explaining the product's use cases, reflecting the challenge of introducing its first foldable into a market where rivals like Samsung, Huawei, and Honor already have years of experience.", "url": "https://www.creativebloq.com/design/advertising/apples-perfect-iphone-duo-tiktoks-nail-foldable-phone-marketing"}]}, {"name": "Launches & Tools", "stories": [{"headline": "Image to ASCII Converter (Website)", "blurb": "Convert JPG, PNG, WebP, or GIF to ASCII art in your browser. Set the width and style, then copy text or export TXT, PNG, or SVG.", "url": "https://imagetoascii.art/"}, {"headline": "Beautiful Loading Indicators for React (Website)", "blurb": "A lightweight library full of beautiful loading indicators for React.", "url": "https://loading.dev/"}, {"headline": "Live Creative Review and Approval AI Platform (Website)", "blurb": "Bring your assets, present at the highest quality, review together, make decisions, and let AI agents apply them, live. All within the same shared context.", "url": "https://www.pactto.com/"}]}, {"name": "Miscellaneous", "stories": [{"headline": "Should UX Designers Learn to Code? (11 minute read)", "blurb": "Whether UX designers should learn to code depends on context: knowing a product's technical materials speeds up workflows and suits lean, bootstrapped teams. Yet coding can invite scope creep, narrow thinking toward technical constraints, and waste time on languages that quickly become obsolete. Teams with more T-shaped members, deep in one field and broadly aware of others, communicate more easily and ship better products faster.", "url": "https://ixdf.org/literature/article/should-ux-designers-learn-to-code"}, {"headline": "That Crisp Interface is Going to Date (5 minute read)", "blurb": "Today's crisp interfaces, with generous white space and a single decisive CTA, will date the way drop shadows and gradients did. Software has never been cheaper to ship, yet it keeps yielding identical landing pages, and AI models serving up the center of the distribution make it worse. Gumroad, Are.na, Substack, and Nothing show the alternative: someone had a default available and chose something else, from oversized type to deliberate friction.", "url": "https://marieclairedean.substack.com/p/that-crisp-interface-is-going-to"}, {"headline": "From YWCA to Hotel Willo: how Rethink solved one of branding's trickiest problems (5 minute read)", "blurb": "Hotel Willo rebranded a Vancouver hotel to overcome outdated perceptions tied to its former YWCA identity, replacing the name with a fresh, approachable brand centered on a simple willow-inspired logo. The identity uses restrained design, playful messaging, and consistent applications to communicate an affordable, welcoming boutique hotel while clearly distancing it from past misconceptions.", "url": "https://www.creativeboom.com/work/from-ywca-to-hotel-willo-how-rethink-solved-a-branding-problem/"}]}, {"name": "Quick Links", "stories": [{"headline": "Seven Artists Reveal the Revelations That Took Their Practice to the Next Level (7 minute read)", "blurb": "Seven artists describe the realizations that took their practice further, from building faces out of geometric forms to dropping the idea of being a watercolor purist.", "url": "https://www.creativebloq.com/creative-inspiration/7-artists-reveal-the-revelations-that-took-their-practice-to-the-next-level"}, {"headline": "Illustrator Rosa Snijders Finds the Softness in Grief, Debt, and All of Life's Heavy Subjects (6 minute read)", "blurb": "Dutch illustrator Rosa Snijders built an editorial career drawing heavy subjects like grief and death for outlets including Le Monde, National Geographic, and Corriere della Sera, using soft palettes rather than grim imagery.", "url": "https://www.creativeboom.com/work/rosa-snijders/"}]}]}, {"title": "TLDR Data — 2026-09-28", "tagline": "Agents Rewire Robot Policies 🤖, Making AI-SQL Much Faster ⚡, Safe Not Safe 🔍", "sections": [{"name": "Deep Dives", "stories": [{"headline": "Robotics Harness Optimization on Graph-as-Policy (11 minute read)", "blurb": "Robotics Harness Optimization used coding agents to evolve a Graph-as-Policy robot controller, boosting simulated throughput 5.27x and success from 67% to 96%. The strongest version only rewired existing skills, without editing them or using human demonstrations.", "url": "https://kael.tech.blog/2026/09/26/robotics-harness-optimization-on-graph-as-policy/"}, {"headline": "Partition Finalization in Pinterest's Next-Generation DB Ingestion Framework (9 minute read)", "blurb": "Pinterest added a finalization layer to its Kafka, Flink, Spark, and Iceberg CDC pipeline so downstream jobs can tell when an hourly partition is safe to read. Flink checkpoints capture event-time statistics, which become Iceberg snapshot metadata and a non-regressing watermark. The reusable signal makes freshness-versus-completeness explicit without introducing another coordination service.", "url": "https://medium.com/pinterest-engineering/partition-finalization-in-pinterests-next-generation-db-ngestion-framework-4c7da6e4cc8f"}, {"headline": "Scaling an ML Inference Pipeline for Batch Workloads (5 minute read)", "blurb": "WHOOP cut a 15.8-million-task internal ML simulation from more than two months to six days by removing per-task HTTP calls, loading the model in workers, and tuning pod CPU. It also documents why Python fork deadlocked native libraries, how spawn fixed it, and how SQS chain state plus atomic S3 writes made retries idempotent.", "url": "https://engineering.whoop.com/scaling-ml-inference-pipeline"}, {"headline": "The guest journey, updated in real time: extending Airbnb's sequence recommender with Chronon (6 minute read)", "blurb": "Airbnb extended Chronon to update guest-journey features from batch refreshes to event-driven processing, cutting feature staleness from roughly two days to under a minute. Push Mode and near-real-time model transforms feed embeddings into online ranking while preserving offline training consistency. The architecture illustrates how feature platforms can bridge streaming updates, experimentation, and low-latency serving.", "url": "https://airbnb.tech/ai-ml/the-guest-journey-updated-in-real-time-extending-airbnbs-sequence-recommender-with-chronon/"}]}, {"name": "Opinions & Advice", "stories": [{"headline": "Ten years of Postgres logical replication (16 minute read)", "blurb": "Postgres logical replication has steadily replaced custom data-movement plumbing with core SQL features: row filters, column lists, partitioned targets, streaming apply, parallel apply, and safer loop prevention. This retrospective connects those releases to practical migration and hub-and-worker scaling patterns. It is a useful checklist for teams revisiting replication slots, failover, write routing, and schema evolution.", "url": "https://tapoueh.org/blog/2026/09/ten-years-of-postgres-logical-replication/"}, {"headline": "What REPACK (CONCURRENTLY) costs while it runs (15 minute read)", "blurb": "PostgreSQL 19 adds built-in REPACK (CONCURRENTLY) for online table rewrites, avoiding extensions while generally running faster and generating less WAL than pg_repack or pg_squeeze. The tradeoffs are significant: it can delay VACUUM across the cluster, briefly block writes during the final swap, and currently has a ceiling of approximately 105 million updates/deletes per run.", "url": "https://boringsql.com/posts/repack-concurrently-costs/"}]}, {"name": "Launches & Tools", "stories": [{"headline": "Building an Ultra-High Throughput AI-SQL Engine (13 minute read)", "blurb": "Quail is an open-source AI-SQL engine that jointly optimizes query planning and LLM inference, running 1.84x faster than tuned vLLM on average and up to 14x faster on some workloads. It reduces wasted KV-cache work and GPU scheduling overhead, making large-scale LLM filtering and joins much cheaper.", "url": "https://fsdatalab.github.io/blog/introducing-quail/"}, {"headline": "Safe Not Safe (Tool)", "blurb": "Safe Not Safe is a browser-based PostgreSQL migration checker that flags risky DDL patterns like blocking locks, rewrites, and unsafe constraint rollouts. It runs entirely locally in the browser, with no API, uploads, logs, or account required.", "url": "https://safenotsafe.dev/"}, {"headline": "Apache Iceberg Views: Portable View Metadata Across SQL Engines (16 minute read)", "blurb": "Iceberg's View Spec makes metadata portable by versioning schemas, dependencies, properties, and dialect-tagged SQL text, but it does not standardize execution or authorization. Production portability still depends on REST-catalog support and compatible SQL dialects. Teams should test dependency integrity, concurrent replacement, and cross-engine result consistency before treating views as shared control-plane assets.", "url": "https://www.dremio.com/blog/apache-iceberg-views-portable-view-metadata-across-sql-engines/"}]}, {"name": "Miscellaneous", "stories": [{"headline": "ALP: Adaptive Lossless Floating-Point Encoding in Apache Parquet (7 minute read)", "blurb": "Apache Parquet added ALP, a new lossless encoding for floating-point data that delivers compression similar to ZSTD while decoding around 10x faster. It also enables much faster random access and parallel decoding, making it especially useful for prices, coordinates, and scientific measurements.", "url": "https://parquet.apache.org/blog/2026/09/22/alp-adaptive-lossless-floating-point-encoding-in-apache-parquet/"}, {"headline": "Trading a Cloud Identity for Your Own: Workload Attestation on Managed Compute (7 minute read)", "blurb": "Netflix describes how Spark jobs on managed compute exchange a cloud execution role for an internally trusted workload identity. A signed metadata payload and AWS identity proof are verified before short-lived certificates are issued for mutual TLS. The pattern separates cloud-provider authorization from application trust, giving the platform stronger workload identity and more auditable access boundaries.", "url": "https://netflixtechblog.com/trading-a-cloud-identity-for-your-own-workload-attestation-on-managed-compute-516d5a29b252"}]}, {"name": "Quick Links", "stories": [{"headline": "The Context Gap | How to build Data Architecture like Open AI (10 minute read)", "blurb": "OpenAI's AI data stack centralizes rich metadata to close the context gap, while a Rust rewrite reportedly cut Airflow scheduling latency 35x at 70,000+ concurrent tasks.", "url": "https://dataopsleadership.substack.com/p/the-context-gap-how-to-build-data"}, {"headline": "DataBench (Tool)", "blurb": "Opus 5.5 leads Hex's DataBench, scoring 70.5% at Max reasoning and 67.0% at XHigh, but at relatively high cost and latency.", "url": "https://hex.tech/databench/"}]}]}]}};
